    assert preview["edit_windows"][1]["line_start"] == 8
    assert any(
        chunk["source"] == "world_preview" and chunk["key"] == "note.txt#1"
        for chunk in client.last_payload["state_context_chunks"]
    )
    assert any(
        chunk["source"] == "world_preview" and chunk["key"] == "note.txt#2"
        for chunk in client.last_payload["state_context_chunks"]
    )


